insert into deposit_types (code, kind, label, description, break_rule, lock_in_months, default_penalty_pct, default_payout, default_tds, min_tenure_months, max_tenure_months, partial_withdrawal, sort) values
 ('fd_post_office', 'fd', 'Post Office Time Deposit', 'India Post TD (1, 2, 3 or 5 years). It cannot be closed in the first 6 months. After that the rate drops, and a 5-year TD opened on or after 10 Nov 2023 cannot be closed before 4 years. Confirm the current rule with your post office.', 'after_lock_in', 6, 2.00, null, true, null, 60, false, 60),
 ('fd_corporate',   'fd', 'Corporate / NBFC FD', 'Fixed deposit with a company such as an NBFC or housing-finance company. Usually cannot be closed in the first 3 months; after that a penalty applies. Not covered by deposit insurance. Terms differ by issuer.', 'after_lock_in', 3, 1.50, null, true, null, null, false, 70),
 ('fd_other',       'fd', 'Other FD (not listed)', 'Any fixed deposit not in this list. Treated as closable early; set the penalty yourself when you close it.', 'allowed', 0, 1.00, null, true, null, null, false, 99),
 ('rd_post_office', 'rd', 'Post Office RD', 'India Post 5-year recurring deposit. It can be closed early only after 3 years, and then at the savings-account rate. It cannot be closed early while advance instalments are outstanding.', 'after_lock_in', 36, 0.00, null, false, 60, 60, false, 40),
 ('rd_other',       'rd', 'Other RD (not listed)', 'Any recurring deposit not in this list. Treated as closable early; set the penalty yourself when you close it.', 'allowed', 0, 1.00, null, true, null, null, false, 99);
